-- Plantillas de trámite del estudio (sin IA). Variables: {{encabezado}}, {{caratula}}, {{expte}}, {{cliente}}.
INSERT INTO public.escrito_templates (user_id, nombre, tipo, categoria, compartido, is_active, contenido_modelo)
SELECT v.* FROM (VALUES
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita pronto despacho', 'Pronto despacho', 'tramite', true, true, '{"titulo":"SOLICITA PRONTO DESPACHO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a solicitar a V.S. se sirva dictar pronto despacho respecto de [PRESENTACIÓN PENDIENTE DE PROVEER], atento al tiempo transcurrido sin que haya sido proveída.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Acompaña cédula diligenciada', 'Acompaña cédula', 'tramite', true, true, '{"titulo":"ACOMPAÑA CÉDULA DILIGENCIADA","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a acompañar cédula de notificación debidamente diligenciada, dirigida a [DESTINATARIO], a fin de que se agregue a autos y surta sus efectos.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita se libre oficio', 'Solicita oficio', 'tramite', true, true, '{"titulo":"SOLICITA SE LIBRE OFICIO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a solicitar se libre oficio a [ORGANISMO O ENTIDAD], a fin de que informe [OBJETO DEL INFORME], en el plazo que V.S. estime corresponder y bajo apercibimiento de ley.","Asimismo, solicito se autorice al suscripto a su diligenciamiento.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Reitera oficio', 'Reitera oficio', 'tramite', true, true, '{"titulo":"REITERA OFICIO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que no habiéndose recibido hasta la fecha la contestación del oficio dirigido a [ORGANISMO O ENTIDAD], librado en fecha [FECHA], vengo a solicitar se reitere el mismo bajo apercibimiento de ley.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Acompaña documentación', 'Acompaña documentación', 'tramite', true, true, '{"titulo":"ACOMPAÑA DOCUMENTACIÓN","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a acompañar [DOCUMENTACIÓN QUE SE ACOMPAÑA], solicitando se la tenga por presentada y se agregue a autos.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Acompaña comprobante de pago', 'Acompaña comprobante', 'tramite', true, true, '{"titulo":"ACOMPAÑA COMPROBANTE DE PAGO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a acompañar comprobante de pago de [CONCEPTO: TASA, APORTES, BONO], en cumplimiento de lo ordenado en autos, solicitando se tenga por cumplido el recaudo y se continúe el trámite según su estado.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Cumple lo ordenado', 'Cumple recaudo', 'tramite', true, true, '{"titulo":"CUMPLE LO ORDENADO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que en cumplimiento de lo ordenado en fecha [FECHA DE LA PROVIDENCIA], vengo a [LO QUE SE CUMPLE], solicitando se tenga por cumplimentado el requerimiento y se ordene la continuidad del trámite.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita se declare la rebeldía', 'Rebeldía', 'tramite', true, true, '{"titulo":"SOLICITA SE DECLARE LA REBELDÍA","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que encontrándose vencido el plazo para contestar la demanda sin que [NOMBRE DEL DEMANDADO] lo hiciera, pese a haber sido debidamente notificado conforme constancias de autos, vengo a solicitar se declare su rebeldía y se continúe el trámite según su estado.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita apertura a prueba', 'Apertura a prueba', 'tramite', true, true, '{"titulo":"SOLICITA APERTURA A PRUEBA","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que encontrándose trabada la litis y existiendo hechos controvertidos, vengo a solicitar se abra la presente causa a prueba.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita se llamen autos para sentencia', 'Autos para sentencia', 'tramite', true, true, '{"titulo":"SOLICITA SE LLAMEN AUTOS PARA SENTENCIA","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que encontrándose la presente causa en estado, vengo a solicitar se llamen autos para sentencia.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Autoriza', 'Autoriza', 'tramite', true, true, '{"titulo":"AUTORIZA","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a autorizar a [NOMBRE Y APELLIDO], DNI N° [DNI], para compulsar las presentes actuaciones, retirar copias, cédulas y oficios, y realizar todo otro trámite de procuración en la presente causa.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Denuncia nuevo domicilio', 'Denuncia domicilio', 'tramite', true, true, '{"titulo":"DENUNCIA NUEVO DOMICILIO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a denunciar el nuevo domicilio [REAL O LEGAL] de [NOMBRE], sito en [DOMICILIO], solicitando se lo tenga presente a sus efectos.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita desarchivo', 'Desarchivo', 'tramite', true, true, '{"titulo":"SOLICITA DESARCHIVO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a solicitar el desarchivo de las presentes actuaciones, a fin de [MOTIVO DEL DESARCHIVO].","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita se tenga presente', 'Se tenga presente', 'tramite', true, true, '{"titulo":"SOLICITA SE TENGA PRESENTE","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que vengo a poner en conocimiento de V.S. que [HECHO QUE SE INFORMA], solicitando se lo tenga presente.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb),
('ceb22752-726c-4377-8f40-2bdccc8c8bbb'::uuid, 'Solicita orden de pago', 'Orden de pago', 'tramite', true, true, '{"titulo":"SOLICITA ORDEN DE PAGO","encabezado_juez":"{{encabezado}}","caratula":"{{caratula}} - Expte. N° {{expte}}","secciones":[{"titulo":"","parrafos":["Que encontrándose depositada en autos la suma de $ [IMPORTE], vengo a solicitar se libre orden de pago a favor de [BENEFICIARIO], por dicho importe con más sus intereses.","Proveer de conformidad, SERÁ JUSTICIA."]}]}'::jsonb)
) AS v(user_id, nombre, tipo, categoria, compartido, is_active, contenido_modelo)
WHERE NOT EXISTS (SELECT 1 FROM public.escrito_templates t WHERE t.categoria = 'tramite' AND t.nombre = v.nombre);
